/**
 * Fixed spoken guidance. Each prompt plays only from a bundled recording
 * that a native speaker has reviewed and approved for that language (see
 * assets/prompts/README.md). If a language has no approved recording for a
 * prompt, LUMA plays nothing for it: it never substitutes another language.
 * TalkBack announcements and on-screen text still give the same guidance.
 *
 * The English text below is what each recording must say; translations are
 * supplied with the recordings by the team, not generated by the app.
 */
export const PROMPT_TEXT = {
  take_photo: 'Take a photo of the page.',
  board_tip: 'Stand where the board fills the screen, then take the photo.',
  reading_page: 'Reading the page. Please wait.',
  scan_complete: 'Scan complete.',
  no_text: 'No words were found. Try again.',
  try_again: 'Try again.',
  too_blurry: 'The photo is blurry. Hold the phone steady and try again.',
  glare: 'Light is shining on the page. Tilt the page and try again.',
  too_dark: 'The photo is too dark. Find more light and try again.',
  recording_started: 'Recording. Tap stop when you finish.',
  answer_ready: 'Your answer is ready.',
} as const;

export type PromptId = keyof typeof PROMPT_TEXT;

export const PROMPT_IDS = Object.keys(PROMPT_TEXT) as PromptId[];
